<?php namespace App\Livewire\Admin; use App\Models\Category; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Livewire\Attributes\Layout; use Livewire\Component; #[Layout('layouts.app')] class ManageCategories extends Component { use AuthorizesRequests; public string $name = ''; public function addCategory(): void { $this->authorize('create', Category::class); $validated = $this->validate(['name' => ['required', 'string', 'max:100', 'unique:categories,name']]); Category::create(['name' => strip_tags($validated['name'])]); $this->reset('name'); session()->flash('status', 'Category added.'); } public function render() { return view('livewire.admin.manage-categories', ['categories' => Category::withCount('foodItems')->get()]); } }